package coinchange

import "testing"

func TestBasicCase(t *testing.T) {
	// coins [1,5,10] amount 11 = 2 coins (10+1)
	if got := CoinChange([]int{1, 5, 10}, 11); got != 2 {
		t.Fatalf("expected 2, got %d", got)
	}
}

func TestGreedyWouldFail(t *testing.T) {
	// coins [1,3,4] amount 6: greedy gives 4+1+1=3, DP gives 3+3=2
	if got := CoinChange([]int{1, 3, 4}, 6); got != 2 {
		t.Fatalf("expected 2, got %d", got)
	}
}

func TestImpossible(t *testing.T) {
	// coins [2] amount 3: impossible
	if got := CoinChange([]int{2}, 3); got != -1 {
		t.Fatalf("expected -1, got %d", got)
	}
}

func TestAmountZero(t *testing.T) {
	if got := CoinChange([]int{1, 5}, 0); got != 0 {
		t.Fatalf("expected 0, got %d", got)
	}
}

func TestSingleCoin(t *testing.T) {
	if got := CoinChange([]int{7}, 14); got != 2 {
		t.Fatalf("expected 2, got %d", got)
	}
}
